export const DYNAMIC_INDEX_SETTING_PATTERNS: readonly RegExp[] = [
  /^index\.blocks\./,
  /^index\.routing\.allocation\.(include|exclude|require)\./,
];

/** Settings that are fixed once the index has been created. */
export const FINAL_INDEX_SETTINGS: ReadonlySet<string> = new Set([
  'index.fast_refresh',
  'index.format',
  'index.mode',
  'index.number_of_shards',
  'index.routing_partition_size',
  'index.routing_path',
  'index.soft_deletes.enabled',
  'index.sort.field',
  'index.sort.missing',
  'index.sort.mode',
  'index.sort.order',
  'index.time_series.es87tsdb_codec.enabled',
  'index.time_series.start_time',
]);

export const FINAL_INDEX_SETTING_PATTERNS: readonly RegExp[] = [/^index\.sort\./];

/** Settings managed by Elasticsearch itself or through dedicated APIs. */
export const INTERNAL_INDEX_SETTINGS: ReadonlySet<string> = new Set([
  'index.allocation.existing_shards_allocator',
  'index.downsample.interval',
  'index.downsample.origin.name',
  'index.downsample.origin.uuid',
  'index.downsample.source.name',
  'index.downsample.source.uuid',
  'index.downsample.status',
  'index.frozen',
  'index.rollup.source.name',
  'index.rollup.source.uuid',
  'index.routing.allocation.disk.watermark.ignore',
  'index.search.throttled',
  'index.shard_limit.group',
  'index.source_only',
  'index.store.snapshot.delete_searchable_snapshot',
  'index.store.snapshot.index_name',
  'index.store.snapshot.index_uuid',
  'index.store.snapshot.partial',
  'index.store.snapshot.repository_name',
  'index.store.snapshot.repository_uuid',
  'index.store.snapshot.snapshot_name',
  'index.store.snapshot.snapshot_uuid',
  'index.verified_before_close',
  'index.version.compatibility',
  'index.version.created',
  'index.xpack.ccr.following_index',
]);

export const INTERNAL_INDEX_SETTING_PATTERNS: readonly RegExp[] = [
  /^index\.version\./,
  /^index\.downsample\./,
  /^index\.rollup\./,
  /^index\.store\.snapshot\.(index|repository|snapshot)_/,
  /^index\.resize\./,
  /^index\.shrink\./,
];
